function renderPlushPage(ctx, isVideo) {
  const { draft, ui, path: path2, navAttrs } = ctx;
  const page = ctx.page;
  const company = draft.company;
  const brand = company.logoAssetId ? `<img src="${esc2(ctx.asset(company.logoAssetId))}" alt="${esc2(company.name)}" style="height:34px;max-width:160px;object-fit:contain;">` : `<span style="font-size:1.2rem;font-weight:900;letter-spacing:-0.03em;color:#371b26;">${esc2(company.name)}</span>`;
  const depth = ctx.depth;
  const languageLinks = (draft.languages || ["zh", "en"]).map((l) => `<a href="${depth}../${l}/${page === "detail" && ctx.options.productId ? `products/${ctx.options.productId}/index.html` : page === "home" ? "index.html" : `${page}/index.html`}" lang="${l}" data-wr-lang="${l}" style="font-size:0.8rem;font-weight:800;padding:4px 8px;border-radius:9999px;text-decoration:none;${l === ctx.lang ? "background:#db2777;color:#ffffff;" : "color:#831843;"}" aria-current="${l === ctx.lang}">${l.toUpperCase()}</a>`).join("");
  const headerHtml = `
    <header class="wr-plush-header" style="position:fixed;top:0;left:0;right:0;z-index:100;background:rgba(255,255,255,0.92);backdrop-filter:blur(20px);border-bottom:1px solid #fce7f3;box-shadow:0 2px 10px rgba(236,72,153,0.03);">
      <div class="wrap" style="display:flex;justify-content:space-between;align-items:center;padding:12px 20px;gap:16px;">
        <a href="${path2("index.html")}" ${navAttrs("home")} style="text-decoration:none;display:inline-flex;align-items:center;gap:8px;">
          ${brand}
        </a>
        <nav aria-label="${esc2(ui.menu)}" style="display:flex;align-items:center;gap:26px;">
          <a href="${path2("index.html")}" ${navAttrs("home")} style="text-decoration:none;font-size:0.9rem;font-weight:800;color:${page === "home" ? "#db2777" : "#371b26"};">${esc2(ui.home)}</a>
          <a href="${path2("catalog/index.html")}" ${navAttrs("catalog")} style="text-decoration:none;font-size:0.9rem;font-weight:800;color:${page === "catalog" ? "#db2777" : "#371b26"};">${esc2(ui.catalog)}</a>
          <a href="${path2("about/index.html")}" ${navAttrs("about")} style="text-decoration:none;font-size:0.9rem;font-weight:800;color:${page === "about" ? "#db2777" : "#371b26"};">${esc2(ui.about)}</a>
          <a href="${path2("contact/index.html")}" ${navAttrs("contact")} style="text-decoration:none;font-size:0.9rem;font-weight:800;color:${page === "contact" ? "#db2777" : "#371b26"};">${esc2(ui.contact)}</a>
        </nav>
        <div style="display:flex;align-items:center;gap:14px;">
          <div class="languages" style="display:flex;gap:4px;">
            ${languageLinks}
          </div>
          <a class="button" href="${path2("contact/index.html")}" ${navAttrs("contact")} style="background:#db2777;color:#ffffff;font-weight:800;padding:8px 18px;border-radius:9999px;font-size:0.84rem;text-decoration:none;">
            Inquire RFQ \u2197
          </a>
        </div>
      </div>
    </header>
  `;
  let mainHtml = "";
  switch (page) {
    case "catalog":
      mainHtml = renderPlushCatalog(ctx);
      break;
    case "detail":
      mainHtml = renderPlushDetail(ctx);
      break;
    case "about":
      mainHtml = renderPlushAbout(ctx);
      break;
    case "contact":
      mainHtml = renderPlushContact(ctx);
      break;
    default:
      mainHtml = renderPlushHome(ctx, isVideo);
      break;
  }
  const footerHtml = `
    <footer style="background:#201018;color:#d1b5c2;padding:48px 0 24px;font-size:0.86rem;border-top:1px solid #371b26;">
      <div class="wrap" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:36px;margin-bottom:32px;">
        <div>
          <div style="font-size:1.25rem;font-weight:900;color:#ffffff;margin-bottom:10px;">${esc2(company.name)}</div>
          <p style="font-size:0.84rem;line-height:1.65;color:#d1b5c2;margin:0 0 12px;">
            Baby-safe soft living and plush toy manufacturing studio for international brands.
          </p>
          <div style="font-size:0.78rem;color:#f472b6;font-weight:700;">OEKO-TEX 100 \xB7 GOTS \xB7 ISO 8124 \xB7 CE Safety \xB7 ISO9001</div>
        </div>

        <div>
          <h4 style="font-size:0.86rem;font-weight:800;color:#ffffff;margin:0 0 12px;text-transform:uppercase;">${esc2(ui.catalog)}</h4>
          <ul style="list-style:none;padding:0;margin:0;display:grid;gap:6px;font-size:0.82rem;">
            <li><a style="text-decoration:none;color:#d1b5c2;" href="${path2("catalog/index.html")}" ${navAttrs("catalog")}>Ergonomic Cushions</a></li>
            <li><a style="text-decoration:none;color:#d1b5c2;" href="${path2("catalog/index.html")}" ${navAttrs("catalog")}>Kawaii Plush Toys</a></li>
            <li><a style="text-decoration:none;color:#d1b5c2;" href="${path2("catalog/index.html")}" ${navAttrs("catalog")}>Infant Soothing Bedding</a></li>
            <li><a style="text-decoration:none;color:#d1b5c2;" href="${path2("catalog/index.html")}" ${navAttrs("catalog")}>Weighted Sensory Plush</a></li>
          </ul>
        </div>

        <div>
          <h4 style="font-size:0.86rem;font-weight:800;color:#ffffff;margin:0 0 12px;text-transform:uppercase;">Atelier Metrics</h4>
          <ul style="list-style:none;padding:0;margin:0;display:grid;gap:6px;font-size:0.82rem;">
            <li>\u2713 800,000 Pcs Monthly Output</li>
            <li>\u2713 100% Cleanroom Manufacturing</li>
            <li>\u2713 0.8mm Dual Needle Detection</li>
            <li>\u2713 7-Day Fast 3D Plush Sampling</li>
          </ul>
        </div>

        <div>
          <h4 style="font-size:0.86rem;font-weight:800;color:#ffffff;margin:0 0 12px;text-transform:uppercase;">${esc2(ui.contact)}</h4>
          <p style="margin:0 0 6px;"><strong>Email:</strong> <a style="color:#f472b6;" href="mailto:${esc2(company.email)}">${esc2(company.email)}</a></p>
          ${company.phone ? `<p style="margin:0 0 6px;"><strong>Phone:</strong> ${esc2(company.phone)}</p>` : ""}
          ${company.address ? `<p style="margin:0;font-size:0.8rem;color:#d1b5c2;">${esc2(company.address)}</p>` : ""}
        </div>
      </div>

      <div class="wrap" style="border-top:1px solid #371b26;padding-top:18px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;font-size:0.8rem;color:#d1b5c2;">
        <div>\xA9 ${(/* @__PURE__ */ new Date()).getUTCFullYear()} ${esc2(company.name)}. ${esc2(ui.rights)}</div>
        <div>\u2601\uFE0F Plush & Cushions Global Trade Edition</div>
      </div>
    </footer>
  `;
  return `${headerHtml}${mainHtml}${footerHtml}`;
}
