function renderApparelPage(ctx, isVideo) {
  const { draft, ui, path: path2, navAttrs } = ctx;
  const page = ctx.page;
  const company = draft.company;
  const brand = company.logoAssetId ? `<img src="${esc2(ctx.asset(company.logoAssetId))}" alt="${esc2(company.name)}" style="height:32px;max-width:160px;object-fit:contain;">` : `<span style="font-size:1.15rem;font-weight:800;letter-spacing:0.04em;color:#18181b;font-family:Georgia, serif;">${esc2(company.name)}</span>`;
  const depth = ctx.depth;
  const languageLinks = (draft.languages || ["zh", "en"]).map((l) => `<a href="${depth}../${l}/${page === "detail" && ctx.options.productId ? `products/${ctx.options.productId}/index.html` : page === "home" ? "index.html" : `${page}/index.html`}" lang="${l}" data-wr-lang="${l}" style="font-size:0.75rem;font-weight:700;padding:3px 6px;border-radius:2px;text-decoration:none;${l === ctx.lang ? "background:#18181b;color:#ffffff;" : "color:#71717a;"}" aria-current="${l === ctx.lang}">${l.toUpperCase()}</a>`).join("");
  const headerHtml = `
    <header class="wr-apparel-header" style="position:fixed;top:0;left:0;right:0;z-index:100;background:rgba(250,249,246,0.92);backdrop-filter:blur(16px);border-bottom:1px solid #e4e4e7;">
      <div class="wrap" style="display:flex;justify-content:space-between;align-items:center;padding:12px 20px;gap:16px;">
        <a href="${path2("index.html")}" ${navAttrs("home")} style="text-decoration:none;display:inline-flex;align-items:center;">
          ${brand}
        </a>
        <nav aria-label="${esc2(ui.menu)}" style="display:flex;align-items:center;gap:24px;">
          <a href="${path2("index.html")}" ${navAttrs("home")} style="text-decoration:none;font-size:0.86rem;font-weight:700;color:${page === "home" ? "#d97706" : "#18181b"};letter-spacing:0.04em;">${esc2(ui.home)}</a>
          <a href="${path2("catalog/index.html")}" ${navAttrs("catalog")} style="text-decoration:none;font-size:0.86rem;font-weight:700;color:${page === "catalog" ? "#d97706" : "#18181b"};letter-spacing:0.04em;">${esc2(ui.catalog)}</a>
          <a href="${path2("about/index.html")}" ${navAttrs("about")} style="text-decoration:none;font-size:0.86rem;font-weight:700;color:${page === "about" ? "#d97706" : "#18181b"};letter-spacing:0.04em;">${esc2(ui.about)}</a>
          <a href="${path2("contact/index.html")}" ${navAttrs("contact")} style="text-decoration:none;font-size:0.86rem;font-weight:700;color:${page === "contact" ? "#d97706" : "#18181b"};letter-spacing:0.04em;">${esc2(ui.contact)}</a>
        </nav>
        <div style="display:flex;align-items:center;gap:12px;">
          <div class="languages" style="display:flex;gap:3px;">
            ${languageLinks}
          </div>
          <a class="button" href="${path2("contact/index.html")}" ${navAttrs("contact")} style="background:#18181b;color:#ffffff;font-weight:700;padding:7px 16px;border-radius:2px;font-size:0.8rem;text-decoration:none;letter-spacing:0.04em;">
            Swatches \u2197
          </a>
        </div>
      </div>
    </header>
  `;
  let mainHtml = "";
  switch (page) {
    case "catalog":
      mainHtml = renderApparelCatalog(ctx);
      break;
    case "detail":
      mainHtml = renderApparelDetail(ctx);
      break;
    case "about":
      mainHtml = renderApparelAbout(ctx);
      break;
    case "contact":
      mainHtml = renderApparelContact(ctx);
      break;
    default:
      mainHtml = renderApparelHome(ctx, isVideo);
      break;
  }
  const footerHtml = `
    <footer style="background:#18181b;color:#a1a1aa;padding:48px 0 24px;font-size:0.84rem;border-top:1px solid #27272a;">
      <div class="wrap" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:36px;margin-bottom:32px;">
        <div>
          <div style="font-size:1.15rem;font-weight:800;color:#ffffff;margin-bottom:10px;font-family:Georgia, serif;">${esc2(company.name)}</div>
          <p style="font-size:0.82rem;line-height:1.65;color:#a1a1aa;margin:0 0 12px;">
            Haute couture atelier and high-performance textile mill for global fashion brands.
          </p>
          <div style="font-size:0.75rem;color:#d97706;font-weight:700;">GOTS \xB7 OEKO-TEX 100 \xB7 GRS \xB7 ISO9001</div>
        </div>

        <div>
          <h4 style="font-size:0.82rem;font-weight:800;color:#ffffff;margin:0 0 10px;text-transform:uppercase;">${esc2(ui.catalog)}</h4>
          <ul style="list-style:none;padding:0;margin:0;display:grid;gap:6px;font-size:0.8rem;">
            <li><a style="text-decoration:none;color:#a1a1aa;" href="${path2("catalog/index.html")}" ${navAttrs("catalog")}>Technical Outerwear</a></li>
            <li><a style="text-decoration:none;color:#a1a1aa;" href="${path2("catalog/index.html")}" ${navAttrs("catalog")}>WholeGarment Knitwear</a></li>
            <li><a style="text-decoration:none;color:#a1a1aa;" href="${path2("catalog/index.html")}" ${navAttrs("catalog")}>Runway Tailoring</a></li>
            <li><a style="text-decoration:none;color:#a1a1aa;" href="${path2("catalog/index.html")}" ${navAttrs("catalog")}>Luxury French Terry</a></li>
          </ul>
        </div>

        <div>
          <h4 style="font-size:0.82rem;font-weight:800;color:#ffffff;margin:0 0 10px;text-transform:uppercase;">Atelier Metrics</h4>
          <ul style="list-style:none;padding:0;margin:0;display:grid;gap:6px;font-size:0.8rem;">
            <li>\u2713 450,000 Pcs Monthly Output</li>
            <li>\u2713 5-Day Fast Sample Turnaround</li>
            <li>\u2713 100% Automated Laser Cutting</li>
            <li>\u2713 Grade 4.5+ Color Fastness</li>
          </ul>
        </div>

        <div>
          <h4 style="font-size:0.82rem;font-weight:800;color:#ffffff;margin:0 0 10px;text-transform:uppercase;">${esc2(ui.contact)}</h4>
          <p style="margin:0 0 6px;"><strong>Email:</strong> <a style="color:#d97706;" href="mailto:${esc2(company.email)}">${esc2(company.email)}</a></p>
          ${company.phone ? `<p style="margin:0 0 6px;"><strong>Phone:</strong> ${esc2(company.phone)}</p>` : ""}
          ${company.address ? `<p style="margin:0;font-size:0.78rem;color:#71717a;">${esc2(company.address)}</p>` : ""}
        </div>
      </div>

      <div class="wrap" style="border-top:1px solid #27272a;padding-top:16px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;font-size:0.78rem;color:#71717a;">
        <div>\xA9 ${(/* @__PURE__ */ new Date()).getUTCFullYear()} ${esc2(company.name)}. ${esc2(ui.rights)}</div>
        <div>\u{1F457} Apparel & Textiles Haute Runway Edition</div>
      </div>
    </footer>
  `;
  return `${headerHtml}${mainHtml}${footerHtml}`;
}
